use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM_PROMPT: &str = "You are a customer-support assistant. Answer the question using only the supplied knowledge. If you need more knowledge, request a lookup with the lookup tool.";
const MAX_QUESTION_CHARS: usize = 512;
const MAX_ROUNDS: usize = 4;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn error(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn build_prompt(intent: Intent, question: &str, knowledge: &[String]) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(intent_label(intent));
    prompt.push_str("\n\nQuestion:\n");
    prompt.push_str(question);
    prompt.push_str("\n\nKnowledge:\n");
    if knowledge.is_empty() {
        prompt.push_str("(none)\n");
    } else {
        for (i, entry) in knowledge.iter().enumerate() {
            prompt.push_str(&format!("{}. {}\n", i + 1, entry));
        }
    }
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Precondition from the contract (len in characters, as in the Python spec).
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return error("question exceeds 512 characters");
        }

        let ConversationContext {
            intent,
            question,
            mut knowledge,
        } = ctx;

        let mut prompt = build_prompt(intent, &question, &knowledge);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM_PROMPT, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(request) => {
                    // Only the `lookup` tool is in this node's scope.
                    if request.tool != "lookup" {
                        return error("model requested a tool outside its scope");
                    }
                    knowledge.extend(kb_read::lookup(&request.query));
                    prompt = build_prompt(intent, &question, &knowledge);
                }
            }
        }

        error("tool loop did not converge within the round limit")
    }
}

export!(Node);
```

